<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Sprout,LayoutDashboard,Utensils,Heart,MessageCircle,ClipboardList,Bell,Settings,ScanLine,BarChart3,Camera,Users,Sliders,FileText,Building2,LogOut,Menu,ArrowUpRight,Leaf} from 'lucide-vue-next'
import {state,logout} from '../api'
import Student from './Student.vue'
import Management from './Management.vue'
const route=useRoute(),router=useRouter(),mobile=ref(false)
const studentLinks=[['/','我的首页',LayoutDashboard],['/menu','今日菜单',Utensils],['/recommend','智能搭配',Heart],['/assistant','营养助手',MessageCircle],['/records','饮食记录',ClipboardList],['/favorites','我的收藏',Heart],['/messages','消息中心',Bell],['/profile','饮食档案',Settings]] as const
const managerLinks=[['/','食堂概览',LayoutDashboard],['/monitor','回收监测',ScanLine],['/analytics','浪费分析',BarChart3],['/dishes','菜品管理',Utensils],['/menus','每日菜单',ClipboardList],['/feedback','意见反馈',MessageCircle],['/devices','设备状态',Camera]] as const
const systemLinks=[['/users','用户与权限',Users],['/canteens','食堂与窗口',Building2],['/models','模型配置',Sliders],['/logs','操作日志',FileText]] as const
const links=computed(()=>state.user?.role==='student'?[...studentLinks]:[...managerLinks,...(state.user?.role==='system_admin'?systemLinks:[])])
const title=computed(()=>links.value.find(x=>x[0]===route.path)?.[1]||({'/messages':'消息中心','/profile':'饮食档案','/settings':'账号设置'}[route.path as string]||'工作台'))
const roleName=computed(()=>({student:'学生工作台',canteen_admin:'食堂工作台',system_admin:'系统工作台'}[state.user!.role]))
async function leave(){await logout();router.push('/login')}
</script>
<template><div class="shell"><aside class="sidebar" :class="{open:mobile}"><router-link class="brand" to="/"><span class="brand-mark"><Sprout/></span><div><b>膳衡</b><small>SHANHENG</small></div></router-link><div class="workspace-label">{{roleName}}</div><nav><router-link v-for="[path,label,icon] in links" :key="path" :to="path" :class="{active:route.path===path}" @click="mobile=false"><component :is="icon" :size="19"/><span>{{label}}</span><span v-if="path==='/assistant'" class="ai-tag">AI</span></router-link></nav><div class="sidebar-bottom"><div class="green-note"><Leaf :size="21"/><b>小份量，大改变</b><p>从每一次按需取餐开始。</p></div><router-link to="/settings"><Settings :size="18"/>账号设置</router-link><button @click="leave"><LogOut :size="18"/>退出登录</button></div></aside><div v-if="mobile" class="mobile-shade" @click="mobile=false"></div><main class="main"><header class="topbar"><div class="row"><button class="icon-button mobile-toggle" @click="mobile=!mobile" aria-label="展开菜单"><Menu/></button><span class="muted">工作台</span><span class="separator">/</span><b>{{title}}</b></div><div class="topbar-right"><el-segmented v-model="state.mode" :options="[{label:'演示数据',value:'demo'},{label:'真实数据',value:'real'}]"/><router-link class="icon-button" to="/messages" aria-label="消息"><Bell :size="19"/></router-link><div class="avatar">{{state.user?.username[0].toUpperCase()}}</div><div class="user-label"><b>{{state.user?.username}}</b><small>{{roleName}}</small></div></div></header><div class="page-content"><div class="page-heading"><div><span class="eyebrow">{{state.user?.role==='student'?'EAT WELL · WASTE LESS':'SMART CANTEEN · BETTER CAMPUS'}}</span><h1>{{title}}</h1></div><span class="date-label">{{new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date())}}</span></div><Student v-if="state.user?.role==='student'||['/profile','/settings','/messages'].includes(route.path)" :page="route.path"/><Management v-else :page="route.path"/><footer class="page-footer"><span>膳衡 SHANHENG · 每一餐，刚刚好</span><span>{{state.mode==='demo'?'当前为演示环境 · 非真实监测结果':'真实记录环境'}} <ArrowUpRight :size="13"/></span></footer></div></main></div></template>
